import React, { useState } from "react";
import BaseLayout from "../../../layouts/BaseLayout";
import axios from "axios";
import "./InviteDoctor.css";
import { PhoneInput } from "react-international-phone";
import "react-international-phone/style.css";
import DoctorsList from "./doctorListingforInvitePage";

const InviteDoctor = () => {
  // State for form fields
  const [firstName, setFirstName] = useState("");
  const [lastName, setLastName] = useState("");
  const [email, setEmail] = useState("");
  const [contact, setContact] = useState("");
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(null);
  const [loading, setLoading] = useState(false);

  // Handle form submission
  const handleSubmit = async (e) => {
    e.preventDefault();
    setError(null);
    setSuccess(null);
    setLoading(true);

    try {
      const response = await axios.post(
        "https://consultant-backend-jiwv.onrender.com/invite-doctor",
        {
          firstName,
          lastName,
          email,
          contact,
        }
      );

      if (response.data) {
        setSuccess("Doctor invitation sent successfully!");
        setFirstName("");
        setLastName("");
        setEmail("");
        setContact("");
      }
    } catch (err) {
      setError("Failed to send invitation. Please try again.");
    }

    setLoading(false);
  };

  return (
    <BaseLayout>
      <div className="justify-between bg-gray-50 p-1 mb-16 flex h-auto">
        <div className="relative flex justify-between p-5 w-[69%]">
          {/* Form Container with Background and Overlay */}
          <div className="form-container w-full max-w-3xl">
            <div className="form-content bg-white shadow-md rounded-lg p-10">
              <form onSubmit={handleSubmit}>
                <div className="flex justify-center">
                  <h3 className="text-xl font-bold mb-6 text-gray-800">
                    Invite New Doctor
                  </h3>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-10 p-10">
                  <div>
                    <label className="block text-gray-600">First Name</label>
                    <input
                      type="text"
                      value={firstName}
                      onChange={(e) => setFirstName(e.target.value)}
                      placeholder="First Name"
                      className="w-full mt-2 p-2 border rounded"
                      required
                    />
                  </div>
                  <div>
                    <label className="block text-gray-600">Last Name</label>
                    <input
                      type="text"
                      value={lastName}
                      onChange={(e) => setLastName(e.target.value)}
                      placeholder="Last Name"
                      className="w-full mt-2 p-2 border rounded"
                      required
                    />
                  </div>
                  <div>
                    <label className="block text-gray-600">Your Email</label>
                    <input
                      type="email"
                      value={email}
                      onChange={(e) => setEmail(e.target.value)}
                      placeholder="Your email"
                      className="w-full mt-2 p-2 border rounded"
                      required
                    />
                  </div>
                  <div>
                    <label className="block text-gray-600">Phone no.</label>
                    <PhoneInput
                      defaultCountry="india"
                      value={contact}
                      onChange={(contact) => setContact(contact)}
                      placeholder="Phone no."
                      className="w-full mt-2 p-2 border rounded"
                      required
                    />
                  </div>
                </div>

                {/* Error and Success Messages */}
                {error && <p className="text-red-500 mt-4">{error}</p>}
                {success && <p className="text-green-500 mt-4">{success}</p>}

                {/* Submit Button */}
                <button
                  type="submit"
                  className={`${
                    loading
                      ? "bg-gray-400 cursor-not-allowed"
                      : "bg-blue-500 hover:bg-blue-600"
                  } text-white py-2 px-4 rounded mt-4 flex justify-center items-center`}
                  disabled={loading}
                >
                  {loading ? (
                    <svg
                      className="animate-spin h-5 w-5 text-white"
                      xmlns="http://www.w3.org/2000/svg"
                      fill="none"
                      viewBox="0 0 24 24"
                    >
                      <circle
                        className="opacity-25"
                        cx="12"
                        cy="12"
                        r="10"
                        stroke="currentColor"
                        strokeWidth="4"
                      ></circle>
                      <path
                        className="opacity-75"
                        fill="currentColor"
                        d="M4 12a8 8 0 018-8v8H4z"
                      ></path>
                    </svg>
                  ) : (
                    "Invite Doctor"
                  )}
                </button>
              </form>
            </div>
          </div>
        </div>
        <DoctorsList />
      </div>
    </BaseLayout>
  );
};

export default InviteDoctor;
